css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; bottom: 0; width: calc(var(--loader-size) * .16); height: calc(var(--loader-size) * .16); border-radius: 50%; background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 65%, transparent), var(--accent)); opacity: 0; animation: rise calc(var(--loader-speed) * 2.2) ease-in infinite; }
.loader span:nth-child(1) { left: 8%; animation-delay: 0s; }
.loader span:nth-child(2) { left: 28%; animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-child(3) { left: 48%; animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-child(5) { left: 86%; animation-delay: calc(var(--loader-speed) * 1.6); }
@keyframes rise { 0% { transform: translateY(0) scale(.4); opacity: 0; } 20% { opacity: .9; } 80% { opacity: .9; } 100% { transform: translateY(calc(var(--loader-size) * -.9)) scale(1); opacity: 0; } }
